<script setup>
import { Head, Link, router } from '@inertiajs/vue3';
import { computed, reactive, watch } from 'vue';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
const props = defineProps({ products: Object, filters: Object, counts: Object, categories: Array, groups: Array, attributeDefinitions: Array });
const toSearch = filters => ({ q: filters.q ?? '', registration_status: filters.registration_status ?? '', publication_status: filters.publication_status ?? '', kind: filters.kind ?? '', category: Number(filters.uncategorized) === 1 ? 'uncategorized' : filters.category_id ?? '', product_group_id: filters.product_group_id ?? '', attribute_definition_id: filters.attribute_definition_id ?? '', attribute_value: filters.attribute_value ?? '' });
const search = reactive(toSearch(props.filters));
watch(() => props.filters, value => Object.assign(search, toSearch(value)));
const filteredDefinitions = computed(() => props.attributeDefinitions.filter(definition => !search.product_group_id || definition.product_group_id === Number(search.product_group_id)));
const selectedDefinition = computed(() => props.attributeDefinitions.find(definition => definition.id === Number(search.attribute_definition_id)));
function changeGroup() { if (!filteredDefinitions.value.some(definition => definition.id === Number(search.attribute_definition_id))) { search.attribute_definition_id = ''; search.attribute_value = ''; } }
function submit() { const { category, ...filters } = search; router.get('/admin/products', { ...filters, category_id: category === 'uncategorized' ? '' : category, uncategorized: category === 'uncategorized' ? 1 : 0 }, { preserveState: true, replace: true }); }
const categoryPaths = computed(() => Object.fromEntries(props.categories.map(category => [category.id, category.path])));
const money = value => value === null ? '未設定' : new Intl.NumberFormat('ja-JP', { maximumFractionDigits: 4 }).format(value);
</script>
<template>
  <AdminLayout>
    <Head title="販売商品管理" />
    <div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs font-bold tracking-widest text-emerald-700">販売商品</p><h1 class="mt-3 text-3xl font-bold">販売商品管理</h1><p class="mt-3 text-sm text-slate-500">販売商品の仮登録・本登録、基本商品、属性、公開状態を管理します。</p></div><Link href="/admin/products/create" class="btn-primary">＋ 販売商品を登録</Link></div>
    <div class="my-7 grid grid-cols-3 gap-3"><div v-for="item in [{ label: 'すべての販売商品', value: counts.all }, { label: '仮登録', value: counts.provisional }, { label: '本登録', value: counts.confirmed }]" :key="item.label" class="rounded-xl border border-slate-200 bg-white p-5"><p class="text-xs text-slate-500">{{ item.label }}</p><p class="mt-2 text-2xl font-semibold">{{ item.value }}<span class="ml-2 text-xs font-normal text-slate-400">件</span></p></div></div>
    <form @submit.prevent="submit" class="mb-6 grid items-end gap-4 rounded-xl border border-slate-200 bg-white p-5 sm:grid-cols-2 lg:grid-cols-3">
      <div><label for="q" class="mb-2 block text-sm font-medium">販売商品名・商品コード</label><input id="q" v-model="search.q" class="field" maxlength="200" placeholder="キーワードで検索" /></div>
      <div><label for="registration" class="mb-2 block text-sm font-medium">登録状態</label><select id="registration" v-model="search.registration_status" class="field"><option value="">すべて</option><option value="provisional">仮登録</option><option value="confirmed">本登録</option></select></div>
      <div><label for="publication" class="mb-2 block text-sm font-medium">公開状態</label><select id="publication" v-model="search.publication_status" class="field"><option value="">すべて</option><option value="private">非公開</option><option value="public">公開</option></select></div><div><label for="kind-filter" class="mb-2 block text-sm font-medium">商品の種類</label><select id="kind-filter" v-model="search.kind" class="field"><option value="">すべて</option><option value="single">単品</option><option value="bundle">セット商品</option></select></div>
      <div><label for="group-filter" class="mb-2 block text-sm font-medium">基本商品</label><select id="group-filter" v-model="search.product_group_id" class="field" @change="changeGroup"><option value="">すべて</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.name }}{{ group.status === 'inactive' ? '（無効）' : '' }}</option></select></div>
      <div><label for="attribute-filter" class="mb-2 block text-sm font-medium">属性項目</label><select id="attribute-filter" v-model="search.attribute_definition_id" class="field" @change="search.attribute_value = ''"><option value="">指定なし</option><option v-for="definition in filteredDefinitions" :key="definition.id" :value="definition.id">{{ definition.group.name }} / {{ definition.name }}</option></select></div>
      <div><label for="attribute-value" class="mb-2 block text-sm font-medium">属性値</label><select v-if="selectedDefinition?.input_type === 'select'" id="attribute-value" v-model="search.attribute_value" class="field"><option value="">値を問わない</option><option v-for="option in selectedDefinition.options" :key="option" :value="option">{{ option }}</option></select><input v-else id="attribute-value" v-model="search.attribute_value" class="field" maxlength="255" :disabled="!search.attribute_definition_id" placeholder="属性値を含む販売商品" /></div>
      <div class="sm:col-span-2"><label for="category-filter" class="mb-2 block text-sm font-medium">商品分類（配下も含む）</label><select id="category-filter" v-model="search.category" class="field"><option value="">すべて</option><option value="uncategorized">未分類</option><option v-for="category in categories" :key="category.id" :value="category.id">{{ category.path }}{{ category.effective_active ? '' : '（無効な階層）' }}</option></select></div>
      <div class="flex items-center gap-3"><button class="btn-primary">検索</button><Link href="/admin/products" class="nav-link text-sm">解除</Link></div>
    </form>
    <section class="overflow-hidden rounded-xl border border-slate-200 bg-white"><div class="border-b border-slate-200 px-5 py-4 text-sm font-semibold">検索結果 <span class="ml-2 text-slate-500">{{ products.total }} 件</span></div><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-slate-500"><tr><th class="px-5 py-4">販売商品</th><th class="px-5 py-4">基本商品・属性</th><th class="px-5 py-4 whitespace-nowrap">登録状態</th><th class="px-5 py-4">公開</th><th class="px-5 py-4">単位</th><th class="px-5 py-4 text-right whitespace-nowrap">標準販売単価</th><th class="px-5 py-4"><span class="sr-only">操作</span></th></tr></thead><tbody>
      <tr v-for="product in products.data" :key="product.id" class="border-t border-slate-100 hover:bg-slate-50"><td class="px-5 py-4"><Link :href="`/admin/products/${product.id}/edit`" class="font-semibold text-emerald-900 break-all">{{ product.name }}</Link><span class="ml-2 rounded-full px-2 py-1 text-xs" :class="product.kind === 'bundle' ? 'bg-blue-50 text-blue-800' : 'bg-slate-100 text-slate-600'">{{ product.kind === 'bundle' ? 'セット商品' : '単品' }}</span><p class="mt-1 text-xs text-slate-400">{{ product.sku }}</p><div class="mt-2 flex max-w-lg flex-wrap gap-1"><span v-for="category in product.categories" :key="category.id" class="rounded bg-slate-100 px-2 py-1 text-xs text-slate-600">{{ categoryPaths[category.id] ?? category.name }}</span><span v-if="!product.categories.length" class="text-xs text-slate-400">未分類</span></div></td><td class="px-5 py-4"><p class="font-medium">{{ product.group?.name ?? '基本商品なし' }}</p><dl v-if="product.attribute_values.length" class="mt-2 space-y-1 text-xs text-slate-500"><div v-for="value in product.attribute_values" :key="value.id"><dt class="inline">{{ value.definition.name }}：</dt><dd class="inline">{{ value.value }}</dd></div></dl></td><td class="px-5 py-4"><span class="whitespace-nowrap rounded-full px-3 py-1 text-xs" :class="product.registration_status === 'confirmed' ? 'bg-emerald-50 text-emerald-800' : 'bg-amber-50 text-amber-800'">{{ product.registration_status === 'confirmed' ? '本登録' : '仮登録' }}</span></td><td class="px-5 py-4 whitespace-nowrap">{{ product.publication_status === 'public' ? '公開' : '非公開' }}</td><td class="px-5 py-4">{{ product.unit.name }}</td><td class="px-5 py-4 text-right tabular-nums">{{ money(product.default_sale_price) }}</td><td class="px-5 py-4"><Link :href="`/admin/products/${product.id}/edit`" class="nav-link whitespace-nowrap">編集 →</Link></td></tr>
      <tr v-if="!products.data.length"><td colspan="7" class="px-6 py-14 text-center"><p class="font-semibold">{{ counts.all ? '条件に一致する販売商品がありません。' : '販売商品はまだ登録されていません。' }}</p><p class="mt-2 text-sm text-slate-500">{{ counts.all ? '検索条件を変更してください。' : '「販売商品を登録」から最初の販売商品を追加しましょう。' }}</p></td></tr>
    </tbody></table></div><nav aria-label="販売商品一覧のページ切り替え" class="flex items-center justify-between border-t border-slate-200 px-5 py-4 text-sm"><span>{{ products.current_page }} / {{ products.last_page }} ページ</span><div class="flex gap-5"><Link v-if="products.prev_page_url" :href="products.prev_page_url" class="nav-link">← 前へ</Link><Link v-if="products.next_page_url" :href="products.next_page_url" class="nav-link">次へ →</Link></div></nav></section>
  </AdminLayout>
</template>
